12	    : ncnn_llm_base(use_vulkan, num_threads > 0 ? num_threads : 4) {
13	    try {
14	        json config;
15	        {
16	            std::ifstream ifs(model_path + "/model.json");
17	            if (!ifs) {
18	                printf("[ncnn_llm_asr] cannot open %s/model.json\n", model_path.c_str());
19	                ok_ = false;
20	                return;
21	            }
22	            ifs >> config;
23	        }
24	        if (config.contains("model_type")) {
25	            model_type_ = config["model_type"].get<std::string>();
26	        }
27	
28	        mel_net_ = std::make_shared<ncnn::Net>();
29	        audio_conv_net_ = std::make_shared<ncnn::Net>();
30	        audio_encoder_net_ = std::make_shared<ncnn::Net>();
31	        text_embed_net_ = std::make_shared<ncnn::Net>();
32	        text_decoder_net_ = std::make_shared<ncnn::Net>();
33	        lm_head_net_ = std::make_shared<ncnn::Net>();
34	
35	        std::shared_ptr<ncnn::Net> nets[] = {mel_net_, audio_conv_net_, audio_encoder_net_,
36	                                             text_embed_net_, text_decoder_net_, lm_head_net_};
37	        for (auto& n : nets) {
38	            if (num_threads > 0) n->opt.num_threads = num_threads;
39	            // Pure fp32 CPU path: the Qwen3-ASR residual stream is large-magnitude, keep full precision.
40	            n->opt.use_fp16_packed = false;
41	            n->opt.use_fp16_storage = false;
42	            n->opt.use_fp16_arithmetic = false;
43	            n->opt.use_bf16_storage = false;
44	        }
45	
46	        auto p = [&](const char* key) {
47	            return model_path + "/" + config["params"][key].get<std::string>();
48	        };
49	        if (mel_net_->load_param(p("mel_param").c_str()) != 0 ||
50	            mel_net_->load_model(p("mel_bin").c_str()) != 0 ||
51	            audio_conv_net_->load_param(p("audio_conv_param").c_str()) != 0 ||
52	            audio_conv_net_->load_model(p("audio_conv_bin").c_str()) != 0 ||
53	            audio_encoder_net_->load_param(p("audio_encoder_param").c_str()) != 0 ||
54	            audio_encoder_net_->load_model(p("audio_encoder_bin").c_str()) != 0 ||
55	            text_embed_net_->load_param(p("text_embed_param").c_str()) != 0 ||
56	            text_embed_net_->load_model(p("text_embed_bin").c_str()) != 0 ||
57	            text_decoder_net_->load_param(p("text_decoder_param").c_str()) != 0 ||
58	            text_decoder_net_->load_model(p("text_decoder_bin").c_str()) != 0 ||
59	            lm_head_net_->load_param(p("lm_head_param").c_str()) != 0 ||
60	            lm_head_net_->load_model(p("lm_head_bin").c_str()) != 0) {
61	            printf("[ncnn_llm_asr] failed to load one or more nets\n");
62	            ok_ = false;
63	            return;
64	        }
65	
66	        // ---- tokenizer ----
67	        std::string type = config["tokenizer"].value("type", std::string("bbpe"));
68	        std::string vocab_file = model_path + "/" + config["tokenizer"]["vocab_file"].get<std::string>();
69	        std::string merges_file = model_path + "/" + config["tokenizer"]["merges_file"].get<std::string>();
