116	int ncnn_llm_asr::feat_out_len(int n) {
117	    // Matches export_modules.feat_out_len, which uses Python floor division.
118	    auto fdiv = [](int a, int b) {
119	        int q = a / b;
120	        if ((a % b != 0) && ((a < 0) != (b < 0))) q--;
121	        return q;
122	    };
123	    int leave = n % 100;
124	    int fl = fdiv(leave - 1, 2) + 1;
125	    return fdiv(fdiv(fl - 1, 2) + 1 - 1, 2) + 1 + (n / 100) * 13;
126	}
