128	ncnn::Mat ncnn_llm_asr::wav_to_logmel(const float* pcm, int n) const {
129	    ncnn::Mat audio(n);
130	    memcpy(audio.data, pcm, (size_t)n * sizeof(float));
131	
132	    ncnn::Mat mel;  // raw power mel, (w = frames, h = n_mels)
133	    {
134	        ncnn::Extractor ex = mel_net_->create_extractor();
135	        ex.input("in0", audio);
136	        ex.extract("out0", mel);
137	    }
138	
139	    int F = n / hop_length_;      // drop the trailing center-pad frame (matches Whisper stft[...,:-1])
140	    if (F > mel.w) F = mel.w;
141	    if (F < 0) F = 0;
142	
143	    ncnn::Mat out(F, n_mels_);    // (w = F, h = n_mels)
144	    float gmax = -1e30f;
145	    for (int i = 0; i < n_mels_; i++) {
146	        const float* src = mel.row(i);
147	        float* dst = out.row(i);
148	        for (int j = 0; j < F; j++) {
149	            float v = src[j];
150	            if (v < 1e-10f) v = 1e-10f;
151	            v = std::log10(v);
152	            dst[j] = v;
153	            if (v > gmax) gmax = v;
154	        }
155	    }
156	    const float floor_v = gmax - 8.0f;
157	    for (int i = 0; i < n_mels_; i++) {
158	        float* dst = out.row(i);
159	        for (int j = 0; j < F; j++) {
160	            float v = dst[j];
161	            if (v < floor_v) v = floor_v;
162	            dst[j] = (v + 4.0f) / 4.0f;
163	        }
164	    }
165	    return out;
166	}
