168	ncnn::Mat ncnn_llm_asr::run_audio(const ncnn::Mat& logmel) const {
169	    const int F = logmel.w;
170	    int L = feat_out_len(F);
171	    const int D = (F + chunk_frames_ - 1) / chunk_frames_;
172	
173	    // Per 100-frame chunk -> audio_conv -> (w = 896, h = tokens_per_chunk).
174	    std::vector<ncnn::Mat> toks;
175	    toks.reserve(D);
176	    int conv_w = 0;
177	    for (int c = 0; c < D; c++) {
178	        ncnn::Mat chunk(chunk_frames_, n_mels_);  // (w = 100, h = 128) single channel
179	        chunk.fill(0.0f);
180	        const int s = c * chunk_frames_;
181	        const int cnt = std::min(chunk_frames_, F - s);
182	        for (int i = 0; i < n_mels_; i++) {
183	            const float* src = logmel.row(i);
184	            float* dst = chunk.row(i);
185	            if (cnt > 0) memcpy(dst, src + s, (size_t)cnt * sizeof(float));
186	        }
187	        ncnn::Mat convout;
188	        {
189	            ncnn::Extractor ex = audio_conv_net_->create_extractor();
190	            ex.input("in0", chunk);
191	            ex.extract("out0", convout);  // (w = 896, h = 13)
192	        }
193	        conv_w = convout.w;
194	        toks.push_back(convout);
195	    }
196	
197	    // Concat over the token axis, then slice to L real tokens.
198	    ncnn::Mat hidden(conv_w, L);
199	    int written = 0;
200	    for (auto& t : toks) {
201	        for (int r = 0; r < t.h && written < L; r++, written++) {
202	            memcpy(hidden.row(written), t.row(r), (size_t)conv_w * sizeof(float));
203	        }
204	    }
205	
206	    ncnn::Mat audio_emb;  // (w = 1024, h = L)
207	    {
208	        ncnn::Extractor ex = audio_encoder_net_->create_extractor();
209	        ex.input("in0", hidden);
210	        ex.extract("out0", audio_emb);
211	    }
212	    return audio_emb;
213	}
