215	std::shared_ptr<ncnn_llm_gpt_ctx> ncnn_llm_asr::prefill(const std::vector<float>& pcm) {
216	    ncnn::Mat logmel = wav_to_logmel(pcm.data(), (int)pcm.size());  // (F, 128)
217	    ncnn::Mat audio_emb = run_audio(logmel);                         // (1024, L)
218	    const int L = audio_emb.h;
219	    printf("[ncnn_llm_asr] audio: samples=%d, mel_frames=%d, audio_tokens=%d\n",
220	           (int)pcm.size(), logmel.w, L);
221	
222	    // Assemble prompt ids: prefix + L audio-pad + suffix.
223	    std::vector<int> token_ids;
224	    token_ids.reserve(prefix_ids_.size() + L + suffix_ids_.size());
225	    for (int t : prefix_ids_) token_ids.push_back(t);
226	    const int first_audio_index = (int)token_ids.size();
227	    for (int i = 0; i < L; i++) token_ids.push_back(audio_pad_id_);
228	    for (int t : suffix_ids_) token_ids.push_back(t);
229	    const int seq_len = (int)token_ids.size();
230	
231	    // Text embeddings, then overwrite the audio-pad slots with the encoder output.
232	    ncnn::Mat token_embed = llm_run_text_embed(*text_embed_net_, token_ids);  // (1024, seq_len)
233	    for (int i = 0; i < L; i++) {
234	        memcpy(token_embed.row(first_audio_index + i), audio_emb.row(i),
235	               (size_t)hidden_size_ * sizeof(float));
236	    }
237	
238	    // Plain RoPE cache, positions 0..seq_len-1, half width (head_dim/2, seq_len).
239	    ncnn::Mat cos_cache, sin_cache;
240	    generate_rope_embed_cache(seq_len, head_dim_, 0, cos_cache, sin_cache, rope_theta_);
241	
242	    // Full causal mask (seq_len, seq_len): 0 on/under diagonal, large negative above.
243	    ncnn::Mat mask(seq_len, seq_len);
244	    mask.fill(0.0f);
245	    for (int i = 0; i < seq_len; i++) {
246	        float* row = mask.row(i);
247	        for (int j = i + 1; j < seq_len; j++) row[j] = -1e38f;
248	    }
249	
250	    KVCache kv_cache;
251	    ncnn::Mat decode_out = llm_run_decoder_with_kv(*text_decoder_net_, token_embed, mask,
252	                                                   cos_cache, sin_cache, kv_cache, attn_cnt_, true);
253	    ncnn::Mat last_hidden = decode_out.row_range(seq_len - 1, 1);
254	    ncnn::Mat logits = llm_run_lm_head(*lm_head_net_, last_hidden);
255	    int next_token_id = argmax1d(logits);
256	
257	    auto ctx = std::make_shared<ncnn_llm_gpt_base_ctx>();
258	    ctx->kv_cache = std::move(kv_cache);
259	    ctx->cur_token = next_token_id;
260	    ctx->position_id = seq_len;
261	    return ctx;
262	}
263	
264	std::shared_ptr<ncnn_llm_gpt_ctx> ncnn_llm_asr::generate(
265	    const std::shared_ptr<ncnn_llm_gpt_ctx>& ctx_in,
266	    const GenerateConfig& cfg,
267	    std::function<void(const std::string&)> callback,
268	    std::vector<int>* out_ids) {
269	
270	    auto ctx = ctx_in->clone();
271	    std::unordered_set<int> history;
272	    history.insert(ctx->cur_token);
273	
274	    for (int step = 0; step < cfg.max_new_tokens; ++step) {
275	        int tok = ctx->cur_token;
276	        if (eos_ids_.count(tok)) break;
277	
278	        if (out_ids) out_ids->push_back(tok);
279	
280	        bool is_special = (tok >= special_id_begin_) ||
281	                          (additional_special_id_set_.find(tok) != additional_special_id_set_.end());
282	        if (!is_special && callback) {
283	            std::string token_text = bpe_->decode({tok}, true);
284	            if (!token_text.empty()) callback(token_text);
285	        }
286	
287	        // Single-token embedding + single-position RoPE.
288	        ncnn::Mat cur_embed = llm_run_text_embed(*text_embed_net_, tok);
289	        ncnn::Mat cos_cache, sin_cache;
290	        generate_rope_embed_cache(1, head_dim_, ctx->position_id, cos_cache, sin_cache, rope_theta_);
291	        ctx->position_id++;
292	
293	        // Incremental mask [1, kv_len+1]: attend to all cached positions + itself.
294	        ncnn::Mat mask(1, ctx->kv_cache[0].first.h + 1);
295	        mask.fill(0.0f);
296	
297	        ncnn::Mat decode_out = llm_run_decoder_with_kv(*text_decoder_net_, cur_embed, mask,
298	                                                       cos_cache, sin_cache, ctx->kv_cache,
299	                                                       attn_cnt_, false);
300	        ncnn::Mat logits = llm_run_lm_head(*lm_head_net_, decode_out);
301	
302	        LlmTokenSampleConfig sample_cfg;
303	        sample_cfg.vocab_size = vocab_size_;
304	        sample_cfg.temperature = cfg.temperature;
305	        sample_cfg.top_p = cfg.top_p;
306	        sample_cfg.top_k = cfg.top_k;
307	        sample_cfg.repetition_penalty = cfg.repetition_penalty;
308	        sample_cfg.do_sample = cfg.do_sample;
309	        int next_id = llm_select_next_token(logits, history, sample_cfg);
310	
311	        ctx->cur_token = next_id;
312	        history.insert(next_id);
313	    }
314	    return ctx;
315	}
