317	std::string ncnn_llm_asr::transcribe(const std::vector<float>& pcm,
318	                                     const GenerateConfig& cfg,
319	                                     std::string* language_out) {
320	    auto ctx = prefill(pcm);
321	    std::vector<int> gen_ids;
322	    generate(ctx, cfg, nullptr, &gen_ids);
323	
324	    // Output layout: <language> <asr_text> <transcription>.
325	    auto it = std::find(gen_ids.begin(), gen_ids.end(), asr_text_id_);
326	    std::vector<int> lang_ids, text_ids;
327	    if (it != gen_ids.end()) {
328	        lang_ids.assign(gen_ids.begin(), it);
329	        text_ids.assign(it + 1, gen_ids.end());
330	    } else {
331	        text_ids = gen_ids;
332	    }
333	    if (language_out) {
334	        std::string lang = bpe_->decode(lang_ids, true);
335	        // Trim, then strip the "language " prefix the model emits (see parse_asr_output).
336	        size_t b = lang.find_first_not_of(" \t\r\n");
337	        size_t e = lang.find_last_not_of(" \t\r\n");
338	        lang = (b == std::string::npos) ? "" : lang.substr(b, e - b + 1);
339	        const std::string prefix = "language ";
340	        if (lang.size() >= prefix.size()) {
341	            std::string head = lang.substr(0, prefix.size());
342	            std::transform(head.begin(), head.end(), head.begin(),
343	                           [](unsigned char c) { return (char)std::tolower(c); });
344	            if (head == prefix) {
345	                lang = lang.substr(prefix.size());
346	                size_t nb = lang.find_first_not_of(" \t\r\n");
347	                lang = (nb == std::string::npos) ? "" : lang.substr(nb);
348	            }
349	        }
350	        *language_out = lang;
351	    }
352	    return bpe_->decode(text_ids, true);
353	}
