inline int argmax1d(const ncnn::Mat& m) {
    const float* p = m;
    int max_idx = 0;
    float max_val = p[0];
    for (int i = 1; i < m.w; ++i) {
        if (p[i] > max_val) {
            max_val = p[i];
            max_idx = i;
        }
    }
    return max_idx;
}
